<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();function scalar(PDO $db,string $sql):float{try{$v=$db->query($sql)->fetchColumn();return (float)($v??0);}catch(Throwable $e){return 0;}}$k=[];$k['active_clients']=scalar($db,"SELECT COUNT(*) FROM clients WHERE status='active'");$k['leads']=scalar($db,'SELECT COUNT(*) FROM leads');$k['pipeline']=scalar($db,"SELECT COALESCE(SUM(estimated_value),0) FROM leads WHERE status IN ('new','contacted','proposal')");$k['won_leads']=scalar($db,"SELECT COUNT(*) FROM leads WHERE status='won'");$k['proposals']=scalar($db,'SELECT COUNT(*) FROM proposals');$k['accepted_proposals']=scalar($db,"SELECT COUNT(*) FROM proposals WHERE status='accepted'");$k['invoice_value']=scalar($db,"SELECT COALESCE(SUM(total),0) FROM invoices WHERE status<>'cancelled'");$k['paid']=scalar($db,"SELECT COALESCE(SUM(amount_paid),0) FROM invoices WHERE status<>'cancelled'");$k['outstanding']=scalar($db,"SELECT COALESCE(SUM(balance_due),0) FROM invoices WHERE status IN ('sent','partially_paid','overdue')");$k['projects']=scalar($db,'SELECT COUNT(*) FROM client_projects');$k['active_projects']=scalar($db,"SELECT COUNT(*) FROM client_projects WHERE status IN ('planning','in_progress','in_review')");$k['overdue_projects']=scalar($db,"SELECT COUNT(*) FROM client_projects WHERE due_date IS NOT NULL AND due_date<CURDATE() AND status NOT IN ('completed','cancelled')");$k['open_tasks']=scalar($db,"SELECT COUNT(*) FROM project_tasks WHERE status IN ('todo','in_progress','review')");$k['open_tickets']=scalar($db,"SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')");$k['sla_risks']=scalar($db,"SELECT COUNT(*) FROM support_tickets WHERE due_at IS NOT NULL AND due_at<NOW() AND status NOT IN ('resolved','closed')");$k['active_staff']=scalar($db,"SELECT COUNT(*) FROM staff_members WHERE employment_status='active'");$win_rate=$k['leads']?100*$k['won_leads']/$k['leads']:0;$accept_rate=$k['proposals']?100*$k['accepted_proposals']/$k['proposals']:0;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Executive BI</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container-fluid py-4"><h1 class="h3">Executive BI & Operations</h1><div class="row g-3 mt-1"><?php foreach($k as $name=>$value):?><div class="col-sm-6 col-xl-3"><div class="card h-100"><div class="card-body"><div class="text-muted text-uppercase small"><?=htmlspecialchars(str_replace('_',' ',$name))?></div><div class="fs-4 fw-bold"><?=is_float($value)&&in_array($name,['pipeline','invoice_value','paid','outstanding'],true)?number_format($value,2):number_format($value)?></div></div></div></div><?php endforeach;?></div><div class="row g-3 mt-1"><div class="col-md-6"><div class="card"><div class="card-body"><h2 class="h6">Sales conversion</h2><p class="mb-1">Lead win rate: <strong><?=number_format($win_rate,1)?>%</strong></p><p class="mb-0">Proposal acceptance: <strong><?=number_format($accept_rate,1)?>%</strong></p></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><h2 class="h6">Operational risk</h2><p class="mb-1">Overdue projects: <strong><?=number_format($k['overdue_projects'])?></strong></p><p class="mb-0">SLA risks: <strong><?=number_format($k['sla_risks'])?></strong></p></div></div></div></div><div class="mt-4"><a class="btn btn-dark" href="reports.php">Report Center</a> <a class="btn btn-outline-dark" href="automation.php">Automation</a> <a class="btn btn-outline-dark" href="bi-alerts.php">Alerts</a></div></main></body></html>